head.script:
scwin.trigger4_onclick = function() {
	var tabNm = "테스트",
		tabKey = "test01";
	var tabOptions = {
		label: tabNm,
		closable: true,
		openAction: "select"
	};
	var contentsOptions = {
		frameMode: "iframe",
		src: "/sample/common_link/tabControl_spaInitCount_WPFF-23_(WSQ-3076)_sub.xml"
	};
	tabControl1.addTab(tabKey, tabOptions, contentsOptions);
	tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
};
scwin.checkVal1 = function() {
	return (document.getElementById('tabControl1_contents_test01') || document.getElementById('mf_tabControl1_contents_test01')).style.display == "block";
};
